constexpr size_t N = 8;
int buf[N];
size_t head = 0, tail = 0;   // indices in [0, N)

bool push(int v) {
    size_t next = (head + 1) % N;
    if (next == tail) return false;   // full
    buf[head] = v;
    head = next;
    return true;
}
bool pop(int& out) {
    if (head == tail) return false;   // empty
    out = buf[tail];
    tail = (tail + 1) & N;
    return true;
}

