questions.modelAnswer:
template <typename T, size_t N>
class Spsc {
    static_assert(N > 0 && (N & (N - 1)) == 0, "N must be a power of two");
    static_assert(std::is_trivially_copyable_v<T>, "memcpy needs trivially copyable T");
    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};
    alignas(64) T buf_[N];
public:
    size_t push_bulk(const T* src, size_t n) {
        size_t h = head_.load(std::memory_order_relaxed);
        size_t t = tail_.load(std::memory_order_acquire);
        n = std::min(n, N - (h - t));                 // free slots
        if (n == 0) return 0;
        size_t i = h & (N - 1);
        size_t first = std::min(n, N - i);            // up to the end
        std::memcpy(buf_ + i, src, first * sizeof(T));
        std::memcpy(buf_, src + first, (n - first) * sizeof(T));
        head_.store(h + n, std::memory_order_release); // publish once
        return n;
    }
    size_t pop_bulk(T* dst, size_t n) {
        size_t t = tail_.load(std::memory_order_relaxed);
        size_t h = head_.load(std::memory_order_acquire);
        n = std::min(n, h - t);                       // available
        if (n == 0) return 0;
        size_t i = t & (N - 1);
        size_t first = std::min(n, N - i);
        std::memcpy(dst, buf_ + i, first * sizeof(T));
        std::memcpy(dst + first, buf_, (n - first) * sizeof(T));
        tail_.store(t + n, std::memory_order_release);  // free slots once
        return n;
    }
};

